type Status = 'idle' | 'ok';
function label(s: Status): string {
  switch (s) {
    case 'idle': return 'Waiting';
    case 'ok': return 'Done';
    default: {
      const _exhaustive: never = s;
      return _exhaustive;
    }
  }
}

